insert into public.authors (id, code, org_id, slug, display_name, legal_name, bio, country, photo_path, website, spelling, is_demo, is_public_domain, status)
values
  ('246833e1-dbe3-5de9-8f29-9d4a8ea37cfa', 'AU-9ZG4W', 'a39f098d-9ca6-54ea-b11a-3d08b933ac4c', 'chidinma-obiora-lane', 'Chidinma Obiora-Lane', 'Chidinma Obiora-Lane', 'Ran a fabric stall in Balogun Market before opening two shops. Writes plain guides for traders who keep the books themselves. This author is invented for the Akana demo.', 'NG', null, null, 'en-GB', true, false, 'active'),
  ('5961817a-3563-5bc8-bfb8-a0da44f321cf', 'AU-8WS7W', 'a39f098d-9ca6-54ea-b11a-3d08b933ac4c', 'efua-dadzie-lamptey', 'Efua Dadzie-Lamptey', 'Efua Dadzie-Lamptey', 'Led a cooperative of cocoa farmers in the Ashanti Region for many years. Writes about leading by listening first. This author is invented for the Akana demo.', 'GH', null, null, 'en-GB', true, false, 'active'),
  ('6ee37cd1-4cf7-5231-b7dd-c3cd253faf2d', 'AU-JKGDQ', '44c2310b-a0d2-5668-b341-02358a22bed3', 'wanjiru-kamau-otieno', 'Wanjiru Kamau-Otieno', 'Wanjiru Kamau-Otieno', 'A former bank branch manager in Nakuru who now runs money evenings for savings groups. Writes about household money in plain words. This author is invented for the Akana demo.', 'KE', null, null, 'en-GB', true, false, 'active'),
  ('faa630d7-aa70-53ad-a174-5e1a221d85ee', 'AU-77Q79', '44c2310b-a0d2-5668-b341-02358a22bed3', 'thandiwe-mokoena-dube', 'Thandiwe Mokoena-Dube', 'Thandiwe Mokoena-Dube', 'A mother of three and former primary school teacher in Soweto. Writes about family life that runs on small routines. This author is invented for the Akana demo.', 'ZA', null, null, 'en-GB', true, false, 'active'),
  ('0b4a999a-b6e2-5a89-a800-168184f2d9f9', 'AU-GFYGM', 'a443aac7-3431-527b-9920-4afdd7d4b7d0', 'meenakshi-iyer-rao', 'Meenakshi Iyer-Rao', 'Meenakshi Iyer-Rao', 'Spent fifteen years as a project lead in Bengaluru software firms. Writes about doing fewer things with more care. This author is invented for the Akana demo.', 'IN', null, null, 'en-GB', true, false, 'active'),
  ('f027b871-3e94-5ae3-bfff-535bb5fa1ce3', 'AU-PVT1E', '4866fab5-9c14-555e-9cf0-2e1404bdbbb4', 'clodagh-ni-fhaolain-burke', 'Clodagh Ní Fhaoláin-Burke', 'Clodagh Ní Fhaoláin-Burke', 'A community mediator in Galway who has sat in on a great many kitchen-table arguments. Writes about saying difficult things kindly. This author is invented for the Akana demo.', 'IE', null, null, 'en-GB', true, false, 'active'),
  ('81739311-544b-51d0-b751-eac228429401', 'AU-JNCDE', '4866fab5-9c14-555e-9cf0-2e1404bdbbb4', 'hester-quarrington', 'Hester Quarrington', 'Hester Quarrington', 'Retrained from retail management to further education teaching at forty-one. Writes for people changing direction mid-career. This author is invented for the Akana demo.', 'GB', null, null, 'en-GB', true, false, 'active'),
  ('1d176ad5-6f6f-579a-ae10-4976bd7b22be', 'AU-N2JS0', '55476faa-5c27-525a-b387-e7d091219e00', 'marcus-delacroix-hayes', 'Marcus Delacroix-Hayes', 'Marcus Delacroix-Hayes', 'Managed restaurant teams in Chicago before moving into operations for a regional chain. Writes about the everyday work of managing people. This author is invented for the Akana demo.', 'US', null, null, 'en-US', true, false, 'active'),
  ('59a52765-e9ac-569b-be9e-3b14927a1880', 'AU-9WVE6', 'b24f7c50-c1a1-5348-82e5-e650d5b62e3a', 'matilda-kershaw-nguyen', 'Matilda Kershaw-Nguyen', 'Matilda Kershaw-Nguyen', 'A youth worker in Brisbane who helps young people set up their first homes. Writes practical guides for living on your own. This author is invented for the Akana demo.', 'AU', null, null, 'en-GB', true, false, 'active'),
  ('401bf78a-448e-5b22-bed4-c81ffdee02db', 'AU-0TKBN', '55476faa-5c27-525a-b387-e7d091219e00', 'olivier-tremblay-singh', 'Olivier Tremblay-Singh', 'Olivier Tremblay-Singh', 'A college learning skills adviser in Toronto. Writes about studying in ways that fit around real life. This author is invented for the Akana demo.', 'CA', null, null, 'en-GB', true, false, 'active'),
  ('af8c9c7b-05f6-5671-8dd7-1be00e9f55ef', 'AU-JKB28', '6da9aa7c-b20c-5de0-979f-4ac03c9a4795', 'friederike-ostwald-rehm', 'Friederike Ostwald-Rehm', 'Friederike Ostwald-Rehm', 'A Hamburg architect who keeps a notebook of small rules for living. Writes about habits that are easy to start and easy to restart. This author is invented for the Akana demo.', 'DE', null, null, 'en-GB', true, false, 'active'),
  ('b76baf8d-6966-5baa-8049-e25a3077e730', 'AU-1DYWF', '3048d2ae-ec3d-59a8-b770-a1a8d5448c94', 'rafael-moreira-lins', 'Rafael Moreira Lins', 'Rafael Moreira Lins', 'A Recife radio presenter who moved cities three times in ten years. Writes about making and keeping friends as an adult. This author is invented for the Akana demo.', 'BR', null, null, 'en-GB', true, false, 'active'),
  ('0b8e7e64-2d1c-5be5-9d68-1c08fd66f4eb', 'AU-PZ9DF', '736c47c6-1e4e-50cb-b36c-efb4d10e2ff7', 'haruka-tanabe-ellis', 'Haruka Tanabe-Ellis', 'Haruka Tanabe-Ellis', 'A Kyoto tea teacher who writes about pauses, evenings and unhurried breaks in a busy week. This author is invented for the Akana demo.', 'JP', null, null, 'en-GB', true, false, 'active'),
  ('96073833-58e0-5ef5-b869-26df902c259a', 'AU-45ERA', '3048d2ae-ec3d-59a8-b770-a1a8d5448c94', 'ximena-ruiz-albarran', 'Ximena Ruiz-Albarrán', 'Ximena Ruiz-Albarrán', 'A Mexico City illustrator who has freelanced for twenty years. Writes about money when income arrives unevenly. This author is invented for the Akana demo.', 'MX', null, null, 'en-US', true, false, 'active'),
  ('6829f5e0-895b-5169-94d3-9ad48a6cde27', 'AU-0KY5N', 'da3551a3-0c0f-5241-9617-90c18feec6b5', 'ligaya-abellera-cruz', 'Ligaya Abellera-Cruz', 'Ligaya Abellera-Cruz', 'A Quezon City guidance counsellor and mother of two teenagers. Writes about staying close to children as they grow up. This author is invented for the Akana demo.', 'PH', null, null, 'en-US', true, false, 'active'),
  ('075a864b-b68e-589c-a323-b8ea53449d87', 'AU-ARMK7', '4dc7318d-75bf-5b7b-82ca-18f687b20f81', 'sofia-hedlund-ahl', 'Sofia Hedlund-Ahl', 'Sofia Hedlund-Ahl', 'An Uppsala family support worker. Writes about couples sharing the running of a home. This author is invented for the Akana demo.', 'SE', null, null, 'en-GB', true, false, 'active'),
  ('36f006f9-ebc2-53ef-99a1-cdb73f481c76', 'AU-1ZS6X', '46f2cd21-9554-55d7-b252-42f53a250723', 'tama-rawiri-hughes', 'Tama Rāwiri-Hughes', 'Tama Rāwiri-Hughes', 'Coached community rugby clubs and later led volunteer teams across Wellington. Writes about teams that share the work. This author is invented for the Akana demo.', 'NZ', null, null, 'en-GB', true, false, 'active'),
  ('6fcea039-ce64-53af-b930-2a4fed7de542', 'AU-7WKXG', '4866fab5-9c14-555e-9cf0-2e1404bdbbb4', 'nadia-farouk-hassan', 'Nadia Farouk-Hassan', 'Nadia Farouk-Hassan', 'An Alexandria secondary school teacher who writes about kinder self-talk and weeks that hold too much. This author is invented for the Akana demo.', 'EG', null, null, 'en-GB', true, false, 'active'),
  ('cc488874-0d11-509c-9882-1ae2f1e2f986', 'AU-7FGRT', '00000000-0000-0000-0000-000000000001', 'arnold-bennett', 'Arnold Bennett', null, 'Arnold Bennett (1867 to 1931). Real author. The original text is in the public domain; the workbook around it is new Akana material.', 'GB', null, null, 'en-GB', false, true, 'active'),
  ('d232ba52-b09d-56d5-8702-775e8f32e716', 'AU-M0SAD', '00000000-0000-0000-0000-000000000001', 'marcus-aurelius', 'Marcus Aurelius', null, 'Marcus Aurelius (121 to 180). Real author. The original text is in the public domain; the workbook around it is new Akana material.', null, null, null, 'en-GB', false, true, 'active'),
  ('d50c290c-01a9-50d2-82be-71b1d35273e6', 'AU-BXMPD', '00000000-0000-0000-0000-000000000001', 'benjamin-franklin', 'Benjamin Franklin', null, 'Benjamin Franklin (1706 to 1790). Real author. The original text is in the public domain; the workbook around it is new Akana material.', null, null, null, 'en-GB', false, true, 'active'),
  ('8c3a73ff-8b9a-5fea-9bad-96451db4b62e', 'AU-P0Q91', '00000000-0000-0000-0000-000000000001', 'charlotte-mason', 'Charlotte M. Mason', null, 'Charlotte M. Mason (1842 to 1923). Real author. The original text is in the public domain; the workbook around it is new Akana material.', 'GB', null, null, 'en-GB', false, true, 'active'),
  ('46ceb86c-ae4e-54d9-b9de-cac92e964078', 'AU-HX8HW', '00000000-0000-0000-0000-000000000001', 'samuel-smiles', 'Samuel Smiles', null, 'Samuel Smiles (1812 to 1904). Real author. The original text is in the public domain; the workbook around it is new Akana material.', 'GB', null, null, 'en-GB', false, true, 'active'),
