  ('eb39218c-45f1-50aa-8b2b-ed0e3314dcc9', 'AK-RPT7D', 'aed30527-b0d0-5c0d-87b4-1438196c73f3', '6da9aa7c-b20c-5de0-979f-4ac03c9a4795', '00000000-0000-0000-0000-00000000000a', 'small-rules-for-ordinary-days-rpt7d', 'Small Rules for Ordinary Days', null, 'Write a few small personal rules and restart them without fuss.', 'personal_development', 'chosen-habits', 'none', 'full', 'demo', true, 'draft', null),
  ('7c730dc1-407c-5203-abbf-43575943d904', 'AK-SDSH9', 'd82bc68f-6e84-59f3-b2ba-a0c0ccaa1766', '6da9aa7c-b20c-5de0-979f-4ac03c9a4795', '00000000-0000-0000-0000-00000000000a', 'the-tidy-week-sdsh9', 'The Tidy Week', null, 'A thirty-minute weekly reset for your space, diary and inbox.', 'personal_development', 'chosen-habits', 'none', 'first_unit', 'demo', true, 'draft', null),
  ('158039cf-0d8a-5575-aaa8-7b2a83d867fa', 'AK-BJ8GJ', '33f16874-4dd6-5da6-8b2f-f40e705c9282', '3048d2ae-ec3d-59a8-b770-a1a8d5448c94', '00000000-0000-0000-0000-00000000000a', 'friends-worth-calling-bj8gj', 'Friends Worth Calling', null, 'Make a short list, reach out first and plan regular catch-ups.', 'relationships', 'companionable-days', 'none', 'full', 'demo', true, 'draft', null),
