  ('32ff9e71-ba38-5ceb-9d66-cfccc5dfaa2c', 'AK-Z9KWR', 'd56fe5b9-b3c1-5402-8361-e580e1cbabe7', '736c47c6-1e4e-50cb-b36c-efb4d10e2ff7', '00000000-0000-0000-0000-00000000000a', 'the-ten-minute-pause-z9kwr', 'The Ten-Minute Pause', null, 'Take one unhurried ten-minute pause a day and notice what is here.', 'wellbeing', 'noticing-more', 'standard', 'full', 'demo', true, 'draft', null),
  ('2726ed25-013f-505d-b117-2e507571ea10', 'AK-T7QC9', '1785f95c-cfc5-5de4-99ee-e95d29f6439a', '736c47c6-1e4e-50cb-b36c-efb4d10e2ff7', '00000000-0000-0000-0000-00000000000a', 'evenings-with-less-light-t7qc9', 'Evenings With Less Light', null, 'Dim the lights, slow the evening and put screens away earlier.', 'wellbeing', 'softer-nights', 'standard', 'first_unit', 'demo', true, 'draft', null),
  ('0c31739f-5919-5d07-b80f-430311e2ab8b', 'AK-5HQVZ', '97ac882f-4823-565e-a8a2-175cc36607c5', '736c47c6-1e4e-50cb-b36c-efb4d10e2ff7', '00000000-0000-0000-0000-00000000000a', 'tea-walks-and-other-breaks-5hqvz', 'Tea, Walks and Other Breaks', null, 'Put small, real breaks into the week and protect them.', 'wellbeing', 'even-pace', 'standard', 'first_unit', 'demo', true, 'draft', null),
