  ('cede332d-a7a1-5c1f-83a6-92bb607b8cbd', 'AK-P48WC', '398612ea-804f-5037-b9b2-3b7e57175524', '4dc7318d-75bf-5b7b-82ca-18f687b20f81', '00000000-0000-0000-0000-00000000000a', 'two-calendars-one-home-p48wc', 'Two Calendars, One Home', null, 'A weekly planning chat so both partners know what is coming.', 'relationships', 'partners-in-step', 'none', 'full', 'demo', true, 'draft', null),
  ('aed10208-f5af-58be-8878-a2b8160cde1b', 'AK-YKY7D', '5b929c8b-0a1d-5871-ad76-c618e365d1e4', '4dc7318d-75bf-5b7b-82ca-18f687b20f81', '00000000-0000-0000-0000-00000000000a', 'splitting-the-load-at-home-yky7d', 'Splitting the Load at Home', null, 'List every household job, including the planning, and share it out.', 'relationships', 'partners-in-step', 'none', 'first_unit', 'demo', true, 'draft', null),
  ('af7b6fd7-85ea-5ccb-9a63-06ff8dee2d5e', 'AK-HJY00', '495a63ac-3b1b-5417-a9bb-040cc73f3741', '46f2cd21-9554-55d7-b252-42f53a250723', '00000000-0000-0000-0000-00000000000a', 'teams-that-carry-it-together-hjy00', 'Teams That Carry It Together', null, 'Share roles, rotate jobs and thank people well.', 'leadership', 'shared-direction', 'none', 'full', 'demo', true, 'draft', null),
  ('63fcb9f4-21f3-5970-b96d-c8c68742eec0', 'AK-S3DMK', '4cb3d13a-987d-5960-abb6-d15322329c34', '46f2cd21-9554-55d7-b252-42f53a250723', '00000000-0000-0000-0000-00000000000a', 'mentoring-someone-new-s3dmk', 'Mentoring Someone New', null, 'Agree goals, meet regularly and let the mentee lead.', 'career', 'work-worth-choosing', 'none', 'first_unit', 'demo', true, 'draft', null),
  ('644c2fc3-eb85-54ad-9ad3-11e678a37f0f', 'AK-PS66T', 'a9980c63-e854-5725-a6ab-af00f007df09', '4866fab5-9c14-555e-9cf0-2e1404bdbbb4', '00000000-0000-0000-0000-00000000000a', 'a-friendlier-voice-inside-ps66t', 'A Friendlier Voice Inside', null, 'Notice harsh self-talk and answer it as a fair friend would.', 'wellbeing', 'seeing-yourself-fairly', 'standard', 'full', 'demo', true, 'draft', null),
  ('63509da4-b86d-5cd0-8ad1-1d9b4026efc6', 'AK-KWZPG', 'd096f607-e11b-5f38-a24d-04797879a61a', '4866fab5-9c14-555e-9cf0-2e1404bdbbb4', '00000000-0000-0000-0000-00000000000a', 'the-overfull-week-kwzpg', 'The Overfull Week', null, 'Sort the week into must, should and could, and drop one thing.', 'wellbeing', 'renewing-energy', 'standard', 'first_unit', 'demo', true, 'draft', null),
  ('a4fd98e1-b956-5f0a-90d5-d50c6633b065', 'AK-QCRRE', 'a6657f46-c23a-5083-897e-e619c9a14f31', '00000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-00000000000a', 'how-to-live-on-24-hours-a-day-qcrre', 'How to Live on 24 Hours a Day', null, 'Use Bennett''s plan for the hours outside work, one evening at a time.', 'productivity', 'purposeful-time', 'none', 'full', 'public_domain', false, 'draft', null),
  ('cef24d0d-387f-50b5-bbc4-2b4411963ff8', 'AK-FN9KB', 'abbbcec0-ae29-5972-a6d8-b79793ead445', '00000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-00000000000a', 'meditations-fn9kb', 'Meditations', null, 'One book of the Meditations each week, with a daily reflection.', 'personal_development', 'chosen-habits', 'none', 'first_unit', 'public_domain', false, 'draft', null),
  ('02685ba3-fbca-5f30-9735-b8cc2249ffe6', 'AK-3TQX1', '22548ee9-15d2-58cc-946d-0e384f23ce18', '00000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-00000000000a', 'the-way-to-wealth-3tqx1', 'The Way to Wealth', null, 'Test Franklin''s sayings on industry and thrift against your own week.', 'finance', 'considered-spending', 'none', 'full', 'public_domain', false, 'draft', null),
  ('bda6fb85-b115-5471-b91b-f9cdf05c6961', 'AK-B9XEG', '2e6f7126-97e3-5301-8de1-8faee0227bdf', '00000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-00000000000a', 'home-education-b9xeg', 'Home Education', null, 'Try Mason''s outdoor hours, short lessons and narration at home.', 'parenting', 'raising-with-care', 'none', 'first_unit', 'public_domain', false, 'draft', null),
